INSERT INTO `` (`content_id`,`menu_id`,`menu_name`,`menu_name_tamil`,`amount`,`image`,`content_text_english`,`content_text_tamil`,`ingredients_text_english`,`ingredients_text_tamil`,`net_weight`,`shelf_life`,`created_date`,`updated_date`,`created_by`) VALUES (1,1,'Moringa Idli Podi','முருங்கை இட்லி பொடி',100.00,'1788603267735_Moringa-Idli-Podi.jpeg','Relieves Fatigue: The nutrients present in moringa leaves help boost energy levels and reduce tiredness.\nImproves Digestion: The pepper, cumin, and asafoetida added to it help improve digestion and reduce stomach discomfort.\nSupports Blood Sugar and Cholesterol Control: The antioxidants in moringa powder help regulate blood sugar levels and reduce bad cholesterol.\nEnhances Immunity: It helps strengthen the body\'s immune system.\nEasy to Consume: It can be easily eaten with idli, dosa, or hot rice by mixing it with sesame oil or ghee.\n','உடல் சோர்வு நீங்கும்:முருங்கை இலைகளில் உள்ள சத்துக்கள் உடல் ஆற்றலை அதிகரித்து, சோர்வைப் போக்குகிறது.\nசெரிமானம் மேம்படும்: இதில் சேர்க்கப்படும் மிளகு, சீரகம் மற்றும் பெருங்காயம் செரிமானத்தை மேம்படுத்தி, வயிற்றுப் பொருமலைக் குறைக்கிறது.\nஇரத்த சர்க்கரை மற்றும் கொழுப்பு: முருங்கை பொடியில் உள்ள ஆன்டிஆக்ஸிடன்ட்டுகள் இரத்த சர்க்கரை அளவைக் கட்டுப்படுத்தவும், கெட்ட கொழுப்பைக் குறைக்கவு உதவுகிறது.\nநோய் எதிர்ப்பு சக்தி: இது உடலின் நோய் எதிர்ப்புச் சக்தியை பலப்படுத்துகிறது.\nஎளிமையான பயன்பாடு: இட்லி, தோசை மற்றும் சூடான சாதத்துடன் நல்லெண்ணெய் அல்லது நெய் சேர்த்து இதை எளிதாக உட்கொள்ளலாம்.','Drumstick leaves (Moringa leaves): 1 to 2 cups (washed thoroughly and air-dried in the shade)\nChana dal (split chickpeas): 1/2 cup; Urad dal (split black gram): 1/2 cup (white or black variety)\nDried red chilies: 4 to 6 (adjust to taste)\nBlack peppercorns: 1 teaspoon\nCumin seeds: 2 teaspoons\nCoriander seeds: 1 tablespoon\nSesame seeds (white or black): 2 tablespoons (optional)\nAsafoetida: A small amount\nTamarind: A small piece (for flavor and longer shelf life – optional)\nSalt: As required\nGingelly oil (sesame oil): 1 teaspoon','முருங்கைக்கீரை: 1 முதல் 2 கப் (நன்றாகக் கழுவி நிழலில் உலர்த்தியது)\nகடலை பருப்பு: 1/2 கப்உளுத்தம் \nபருப்பு: 1/2 கப் (வெள்ளை அல்லது கருப்பு உளுந்து)\nகாய்ந்த மிளகாய்: 4 முதல் 6 (காரத்திற்கேற்ப)\nமிளகு: 1 டீஸ்பூன்\nசீரகம்: 2 டீஸ்பூன்\nமல்லி விதை (தனியா): 1 டேபிள் ஸ்பூன்\nஎள்ளு (வெள்ளை அல்லது கருப்பு): 2 டேபிள் ஸ்பூன் (விரும்பினால்)\nபெருங்காயம்: சிறிதளவு\nபுளி: சிறிய துண்டு (சுவை மற்றும் ஆயுள் நீடிக்க - விருப்பத்திற்கேற்ப)\nஉப்பு: தேவையான அளவு\nநல்லெண்ணெய்:1 டீஸ்பூன்','100G','3 Months','2026-09-05 15:44:27','2026-09-21 15:06:35',NULL);
INSERT INTO `` (`content_id`,`menu_id`,`menu_name`,`menu_name_tamil`,`amount`,`image`,`content_text_english`,`content_text_tamil`,`ingredients_text_english`,`ingredients_text_tamil`,`net_weight`,`shelf_life`,`created_date`,`updated_date`,`created_by`) VALUES (2,2,'Moringa Rice Podi','முருங்கைக்கீரை சாதப் பொடி',100.00,'1788871478500_Moringa-Rice-Podi.jpeg','Aromatic and hand-roasted rice companion mix (Satha Podi) packed with the goodness of organic Moringa leaves. Stir into hot steamed rice with a dollop of ghee or cold-pressed sesame oil for an instant, healthy, and traditional meal.','இயற்கை முருங்கை இலைகளின் நன்மைகள் நிறைந்த வாசனைமிக்க சாதப் பொடி. சூடான சாதத்தில் சிறிது நெய் அல்லது நல்லெண்ணெய் கலந்து உடனடியாக ஆரோக்கியமான பாரம்பரிய உணவை அனுபவியுங்கள்.','','','100 G','3 Month','2026-09-08 18:14:38','2026-09-08 18:16:25',NULL);
INSERT INTO `` (`content_id`,`menu_id`,`menu_name`,`menu_name_tamil`,`amount`,`image`,`content_text_english`,`content_text_tamil`,`ingredients_text_english`,`ingredients_text_tamil`,`net_weight`,`shelf_life`,`created_date`,`updated_date`,`created_by`) VALUES (3,3,'Moringa Rasam Podi','முருங்கை ரசம் பொடி',100.00,'1788872273115_Moringa-Rasam-Podi.jpeg','Moringa Rasam Podi is a traditional South Indian spice blend made by combining dried drumstick (moringa) leaves with aromatic spices like coriander, cumin, and black pepper.','முருங்கைக்கீரை ரசம் பொடி என்பது, உலர்த்தப்பட்ட முருங்கைக்கீரையுடன் மல்லி, சீரகம் மற்றும் மிளகு போன்ற நறுமணமிக்க மசாலாப் பொருட்களைச் சேர்த்துத் தயாரிக்கப்படும் ஒரு பாரம்பரிய தென்னிந்திய மசாலா கலவையாகும்.','','','100 G','3 Month','2026-09-08 18:27:53','2026-09-08 18:27:53',NULL);
INSERT INTO `` (`content_id`,`menu_id`,`menu_name`,`menu_name_tamil`,`amount`,`image`,`content_text_english`,`content_text_tamil`,`ingredients_text_english`,`ingredients_text_tamil`,`net_weight`,`shelf_life`,`created_date`,`updated_date`,`created_by`) VALUES (4,4,'Moringa Soup Podi','முருங்கை சூப் பொடி',150.00,'1788872359667_Moringa-Soup-Podi.jpeg','Healthy and instant drumstick leaves soup mix. Handcrafted with Moringa leaves and warming South Indian spices. \nJust add a spoonful to hot water, boil for two minutes, and enjoy a comforting, immunity-boosting soup.','ஆரோக்கியமான உடனடி முருங்கை சூப் பொடி. முருங்கை இலைகள் மற்றும் தென்னிந்திய மசாலாப் பொருட்களுடன் பாரம்பரியமாக தயாரிக்கப்பட்டது. \nஒரு ஸ்பூன் பொடியை சுடுநீரில் சேர்த்து இரண்டு நிமிடங்கள் கொதிக்க வைத்து நோய் எதிர்ப்புச் சக்தியை அதிகரிக்கும் சூப்பை பருகுங்கள்.','','','100 G','3 Month','2026-09-08 18:29:19','2026-09-08 18:29:19',NULL);
INSERT INTO `` (`content_id`,`menu_id`,`menu_name`,`menu_name_tamil`,`amount`,`image`,`content_text_english`,`content_text_tamil`,`ingredients_text_english`,`ingredients_text_tamil`,`net_weight`,`shelf_life`,`created_date`,`updated_date`,`created_by`) VALUES (5,5,'Moringa Thuvaiyal','முருங்கைக்கீரைத் துவையல்',150.00,'1788872652371_Moringa-Thuvaiyal.jpeg','Moringa Thuvaiyal (also known as Murungai Keerai Thogayal) is a traditional, iron-rich South Indian thick chutney made with fresh drumstick leaves, lentils, and spices, best served mixed with hot steamed rice and ghee.','முருங்கைக்கீரைத் துவையல் என்பது முருங்கைக்கீரை, பருப்பு வகைகள் மற்றும் மசாலாப் பொருட்களைக் கொண்டு செய்யப்படும், இரும்புச்சத்து நிறைந்த ஒரு பாரம்பரியமான தென்னிந்திய வகை கெட்டிச் சட்னி ஆகும்; இது சூடான சாதம் மற்றும் நெய்யுடன் கலந்து சாப்பிட மிகவும் சுவையாக இருக்கும்.','','','100 G','1 Weeks','2026-09-08 18:34:12','2026-09-08 18:34:12',NULL);
INSERT INTO `` (`content_id`,`menu_id`,`menu_name`,`menu_name_tamil`,`amount`,`image`,`content_text_english`,`content_text_tamil`,`ingredients_text_english`,`ingredients_text_tamil`,`net_weight`,`shelf_life`,`created_date`,`updated_date`,`created_by`) VALUES (6,6,'Pirandai Idli Podi','பிறண்டை இட்லி பொடி',100.00,'1788873281325_Pirandai-idli-Podi.jpeg','Nutritious traditional Pirandai Podi crafted from thoroughly cleaned organic Adamant Creeper stems. \nAcclaimed in Ayurveda and Siddha medicine for promoting bone density, relieving joint pain, and improving overall digestion.','சுத்தம் செய்யப்பட்ட இயற்கை பிரண்டை தண்டுகளிலிருந்து தயாரிக்கப்பட்ட சத்தான பிரண்டை பொடி. எலும்புகளின் அடர்த்தியை அதிகரிக்கவும், மூட்டு வலியைப் போக்கவும், \nசெரிமானத்தை மேம்படுத்தவும் ஆயுர்வேதம் மற்றும் சித்த மருத்துவத்தில் பரிந்துரைக்கப்படுகிறது.','','','100 G','3 Month','2026-09-08 18:44:41','2026-09-08 18:44:41',NULL);
INSERT INTO `` (`content_id`,`menu_id`,`menu_name`,`menu_name_tamil`,`amount`,`image`,`content_text_english`,`content_text_tamil`,`ingredients_text_english`,`ingredients_text_tamil`,`net_weight`,`shelf_life`,`created_date`,`updated_date`,`created_by`) VALUES (7,7,'Pirandai Rice Podi','பிரண்டை சாதப்பொடி',100.00,'1788874035437_Pirandai-satha-Podi.jpeg','Pirandai Rice Powder is a traditional South Indian spice powder made primarily from Pirandai (Cissus quadrangularis), along with roasted urad dal (black gram), chana dal (Bengal gram), dried red chilies, and various spices. It is typically mixed with hot steamed rice and ghee or sesame oil before eating. This flavorful and nutritious powder is commonly enjoyed as a simple and healthy meal accompaniment.','பிரண்டை சாதப்பொடி என்பது பிரண்டையை முதன்மைப் பொருளாகக் கொண்டு, உளுந்தம்பருப்பு, கடலைப்பருப்பு, காய்ந்த மிளகாய் மற்றும் மசாலாப் பொருட்களை வறுத்து அரைக்கப்படும் ஒரு பாரம்பரிய உணவுப் பொடி வகை ஆகும். இதனை சூடான சாதம் மற்றும் நெய் அல்லது நல்லெண்ணெயுடன் சேர்த்து பிசைந்து சாப்பிடுவார்கள்.','','','100 G','3 Month','2026-09-08 18:53:16','2026-09-08 18:57:15',NULL);
INSERT INTO `` (`content_id`,`menu_id`,`menu_name`,`menu_name_tamil`,`amount`,`image`,`content_text_english`,`content_text_tamil`,`ingredients_text_english`,`ingredients_text_tamil`,`net_weight`,`shelf_life`,`created_date`,`updated_date`,`created_by`) VALUES (8,8,'Pirandai Rasam Podi','பிறண்டை ரசம் பொடி',100.00,'1788957019353_Pirandai-Rasam-Podi.jpeg','Pirandai Rasam Podi is a traditional herbal spice mix made from pirandai (Cissus quadrangularis) and aromatic spices. It is known for its digestive benefits, helping to reduce indigestion, bloating, and gas while improving appetite. Rich in calcium and essential minerals, it supports bone strength and joint health. Regular consumption may also help boost immunity, reduce inflammation, and promote overall well-being. When prepared as rasam and included in a balanced diet, Pirandai Rasam Podi can be a healthy addition to daily meals.','பிரண்டை ரசம் பொடி என்பது பிரண்டை (Cissus quadrangularis) மற்றும் நறுமண மசாலாப் பொருட்களைக் கொண்டு தயாரிக்கப்படும் பாரம்பரிய மூலிகைச் சுவையூட்டுப் பொடியாகும். இது செரிமானத்தை மேம்படுத்தி, அஜீரணம், வயிற்று உப்புசம் மற்றும் வாயுத் தொல்லை போன்ற பிரச்சினைகளைக் குறைக்க உதவுகிறது. கால்சியம் மற்றும் அத்தியாவசிய தாதுச் சத்துகள் நிறைந்துள்ளதால், எலும்புகள் மற்றும் மூட்டுகளின் ஆரோக்கியத்தைப் பராமரிக்க உதவுகிறது. தொடர்ந்து அளவோடு உட்கொள்வதால் நோய் எதிர்ப்பு சக்தியை மேம்படுத்தவும், உடலில் ஏற்படும் அழற்சியைக் குறைக்கவும், ஒட்டுமொத்த உடல் நலனை ஆதரிக்கவும் உதவக்கூடும். ரசமாக தயாரித்து சமச்சீர் உணவுடன் சேர்த்துச் சாப்பிடும்போது, பிரண்டை ரசம் பொடி அன்றாட உணவில் ஆரோக்கியமான மற்றும் சத்தான சேர்க்கையாக அமைகிறது.','','','100 G','3 Month','2026-09-09 18:00:19','2026-09-09 18:00:19',NULL);
INSERT INTO `` (`content_id`,`menu_id`,`menu_name`,`menu_name_tamil`,`amount`,`image`,`content_text_english`,`content_text_tamil`,`ingredients_text_english`,`ingredients_text_tamil`,`net_weight`,`shelf_life`,`created_date`,`updated_date`,`created_by`) VALUES (9,9,'Pirandai Thuvaiyal','பிரண்டை துவையல்',150.00,'1788957176391_Pirandai-Thuvaiyal.jpeg','Pirandai Thuvaiyal is a traditional South Indian chutney made from pirandai (Cissus quadrangularis). It is well known for its digestive benefits and helps reduce indigestion, bloating, and gas. Rich in calcium and essential minerals, it supports bone strength and joint health. Regular consumption may help improve appetite, boost immunity, and reduce inflammation in the body. Pirandai Thuvaiyal is also valued in traditional diets for promoting overall health and well-being when consumed as part of a balanced meal.','பிரண்டை துவையல் என்பது பிரண்டை (Cissus quadrangularis) கொண்டு தயாரிக்கப்படும் பாரம்பரிய தென்னிந்திய உணவுப் பதார்த்தமாகும். இது செரிமானத்தை மேம்படுத்தி, அஜீரணம், வயிற்று உப்புசம் மற்றும் வாயுத் தொல்லை போன்ற பிரச்சினைகளைக் குறைக்க உதவுகிறது. கால்சியம் மற்றும் அத்தியாவசிய தாதுச் சத்துகள் நிறைந்துள்ளதால், எலும்புகள் மற்றும் மூட்டுகளின் ஆரோக்கியத்தைப் பாதுகாக்க உதவுகிறது. தொடர்ந்து அளவோடு உட்கொள்வதால் பசியைத் தூண்டவும், நோய் எதிர்ப்பு சக்தியை மேம்படுத்தவும், உடலில் ஏற்படும் அழற்சியைக் குறைக்கவும் உதவலாம். சமச்சீர் உணவுடன் சேர்த்து சாப்பிடும் போது, பிரண்டை துவையல் ஒட்டுமொத்த உடல் நலனை மேம்படுத்தும் ஆரோக்கியமான உணவாக அமைகிறது.','','','100 G','1 Week','2026-09-09 18:02:56','2026-09-09 18:02:56',NULL);
INSERT INTO `` (`content_id`,`menu_id`,`menu_name`,`menu_name_tamil`,`amount`,`image`,`content_text_english`,`content_text_tamil`,`ingredients_text_english`,`ingredients_text_tamil`,`net_weight`,`shelf_life`,`created_date`,`updated_date`,`created_by`) VALUES (10,10,'Karuveppilai Idli Podi','கருவேப்பிலை இட்லி பொடி',100.00,'1788958126234_Karuveppilai-Idli-Podi.jpeg','Karuveppilai (Curry Leaves) Idli Podi is a nutritious South Indian spice powder made with curry leaves, lentils, and spices. Curry leaves are rich in antioxidants, iron, calcium, and essential vitamins that support overall health. Regular consumption may help improve digestion, support healthy blood sugar levels, and boost immunity. The iron content in curry leaves may help prevent iron deficiency and support healthy blood circulation. It also contributes to healthy hair and skin while providing a flavorful and nutritious accompaniment to idli, dosa, and rice.','கறிவேப்பிலை இட்லி பொடி என்பது கறிவேப்பிலை, பருப்புகள் மற்றும் மசாலாப் பொருட்களைக் கொண்டு தயாரிக்கப்படும் சத்தான உணவுப் பொடியாகும். கறிவேப்பிலையில் ஆன்டி ஆக்சிடன்ட்கள், இரும்புச்சத்து, கால்சியம் மற்றும் பல்வேறு வைட்டமின்கள் நிறைந்துள்ளன. இது செரிமானத்தை மேம்படுத்தவும், நோய் எதிர்ப்பு சக்தியை அதிகரிக்கவும், இரத்த சர்க்கரை அளவை சீராக பராமரிக்கவும் உதவக்கூடும். இதில் உள்ள இரும்புச்சத்து, இரத்த சோகையைத் தடுக்கவும், ரத்த ஓட்டத்தை மேம்படுத்தவும் உதவுகிறது. மேலும், தலைமுடி மற்றும் தோல் ஆரோக்கியத்தைப் பேணுவதற்கும் உதவுகிறது. இட்லி, தோசை அல்லது சாதத்துடன் சேர்த்து சாப்பிடுவதன் மூலம் சுவையுடனும் ஆரோக்கியத்துடனும் பல நன்மைகளைப் பெறலாம்.','','','100 G','3 Month','2026-09-09 18:18:46','2026-09-09 18:18:46',NULL);
INSERT INTO `` (`content_id`,`menu_id`,`menu_name`,`menu_name_tamil`,`amount`,`image`,`content_text_english`,`content_text_tamil`,`ingredients_text_english`,`ingredients_text_tamil`,`net_weight`,`shelf_life`,`created_date`,`updated_date`,`created_by`) VALUES (11,11,'Karuveppilai Satha Podi','கருவேப்பிலை சாதப் பொடி',100.00,'1788958227522_Karuveppilai-Satha-Podi.jpeg','Karuveppilai Sadha Podi (Curry Leaf Rice Powder) is a traditional South Indian spice blend made with curry leaves, lentils, and aromatic spices. Curry leaves are rich in iron, calcium, fiber, and antioxidants that help support overall health. Regular consumption may help improve digestion, boost immunity, and maintain healthy blood sugar levels. The iron content supports healthy hemoglobin levels and may help prevent iron deficiency. Curry leaves are also known to promote healthy hair and skin. When mixed with rice and consumed as part of a balanced diet, Karuveppilai Sadha Podi provides both nutrition and flavor.','கறிவேப்பிலை சாதப் பொடி என்பது கறிவேப்பிலை, பருப்புகள் மற்றும் நறுமண மசாலாப் பொருட்களைக் கொண்டு தயாரிக்கப்படும் பாரம்பரிய தென்னிந்திய உணவுப் பொடியாகும். கறிவேப்பிலையில் இரும்புச்சத்து, கால்சியம், நார்ச்சத்து மற்றும் ஆன்டி ஆக்சிடன்ட்கள் நிறைந்துள்ளன. இது செரிமானத்தை மேம்படுத்தவும், நோய் எதிர்ப்பு சக்தியை அதிகரிக்கவும், இரத்த சர்க்கரை அளவை சீராக பராமரிக்கவும் உதவக்கூடும். இதில் உள்ள இரும்புச்சத்து, ஹீமோகுளோபின் அளவை ஆதரித்து இரத்த சோகை ஏற்படுவதைத் தடுக்க உதவுகிறது. மேலும், தலைமுடி மற்றும் தோல் ஆரோக்கியத்தைப் பேணுவதற்கும் உதவுகிறது. சாதத்துடன் கலந்து சாப்பிடும் போது, கறிவேப்பிலை சாதப் பொடி சுவையுடனும் சத்துடனும் உடலுக்கு பல ஆரோக்கிய நன்மைகளை வழங்குகிறது.','','','100 G','3 Month','2026-09-09 18:20:04','2026-09-09 18:20:27',NULL);
INSERT INTO `` (`content_id`,`menu_id`,`menu_name`,`menu_name_tamil`,`amount`,`image`,`content_text_english`,`content_text_tamil`,`ingredients_text_english`,`ingredients_text_tamil`,`net_weight`,`shelf_life`,`created_date`,`updated_date`,`created_by`) VALUES (12,12,'Karuveppilai Thuvaiyal','கருவேப்பிலை துவையல்',150.00,'1788958329011_Karuveppilai-Thuvaiyal.jpeg','Karuveppilai Thuvaiyal (Curry Leaf Chutney) is a traditional South Indian dish made from fresh curry leaves, spices, and other nutritious ingredients. Curry leaves are rich in iron, calcium, fiber, and antioxidants that help support overall health. Regular consumption may help improve digestion, boost immunity, and support healthy blood circulation. The iron content in curry leaves may help prevent iron deficiency and maintain healthy hemoglobin levels. Curry leaves are also known to promote healthy hair growth and support skin health. When included as part of a balanced diet, Karuveppilai Thuvaiyal can be a flavorful and nutritious addition to daily meals.','கறிவேப்பிலை துவையல் என்பது கறிவேப்பிலை, மசாலாப் பொருட்கள் மற்றும் பிற சத்தான பொருட்களைக் கொண்டு தயாரிக்கப்படும் பாரம்பரிய தென்னிந்திய உணவாகும். கறிவேப்பிலையில் இரும்புச்சத்து, கால்சியம், நார்ச்சத்து மற்றும் ஆன்டி ஆக்சிடன்ட்கள் அதிகமாக உள்ளன. இது செரிமானத்தை மேம்படுத்தவும், நோய் எதிர்ப்பு சக்தியை அதிகரிக்கவும், ரத்த ஓட்டத்தை சீராக பராமரிக்கவும் உதவக்கூடும். இதில் உள்ள இரும்புச்சத்து, ஹீமோகுளோபின் அளவை மேம்படுத்தி இரத்த சோகை ஏற்படுவதைத் தடுக்க உதவுகிறது. மேலும், தலைமுடி வளர்ச்சியை ஊக்குவிக்கவும், தோல் ஆரோக்கியத்தைப் பாதுகாக்கவும் கறிவேப்பிலை உதவுகிறது. சமச்சீர் உணவுடன் சேர்த்து உட்கொள்ளும்போது, கறிவேப்பிலை துவையல் சுவையுடனும் சத்துடனும் உடலுக்கு பல ஆரோக்கிய நன்மைகளை வழங்குகிறது.','','','100 G','1 Weeks','2026-09-09 18:22:09','2026-09-09 18:22:09',NULL);
INSERT INTO `` (`content_id`,`menu_id`,`menu_name`,`menu_name_tamil`,`amount`,`image`,`content_text_english`,`content_text_tamil`,`ingredients_text_english`,`ingredients_text_tamil`,`net_weight`,`shelf_life`,`created_date`,`updated_date`,`created_by`) VALUES (13,13,'Ellu Idli Podi','எள்ளு இட்லி பொடி',100.00,'1788958844655_Ellu-Idli-Podi.jpg','Ellu Idli Podi (Sesame Idli Powder) is a nutritious South Indian spice blend made with sesame seeds, lentils, and spices. Sesame seeds are rich in calcium, iron, healthy fats, protein, and antioxidants that support overall health. Regular consumption may help strengthen bones and teeth, improve heart health, and support healthy blood circulation. The fiber content aids digestion and promotes gut health. Sesame seeds are also known to provide energy, support skin and hair health, and help maintain overall wellness. When served with idli, dosa, or rice, Ellu Idli Podi adds both flavor and nutrition to everyday meals.','எள்ளு இட்லி பொடி என்பது எள், பருப்புகள் மற்றும் மசாலாப் பொருட்களைக் கொண்டு தயாரிக்கப்படும் சத்தான தென்னிந்திய உணவுப் பொடியாகும். எள்ளில் கால்சியம், இரும்புச்சத்து, ஆரோக்கியமான கொழுப்புச் சத்துகள், புரதம் மற்றும் ஆன்டி ஆக்சிடன்ட்கள் அதிகமாக உள்ளன. இது எலும்புகள் மற்றும் பற்களை வலுப்படுத்தவும், இதய ஆரோக்கியத்தை மேம்படுத்தவும், ரத்த ஓட்டத்தை சீராக பராமரிக்கவும் உதவக்கூடும். இதில் உள்ள நார்ச்சத்து செரிமானத்தை மேம்படுத்தி குடல் ஆரோக்கியத்தை ஆதரிக்கிறது. மேலும், எள் உடலுக்கு ஆற்றலை வழங்குவதுடன், தோல் மற்றும் தலைமுடி ஆரோக்கியத்தையும் பேண உதவுகிறது. இட்லி, தோசை அல்லது சாதத்துடன் சேர்த்து சாப்பிடும் போது, எள்ளு இட்லி பொடி சுவையுடனும் சத்துடனும் பல ஆரோக்கிய நன்மைகளை வழங்குகிறது.','','','100 G','3 Month','2026-09-09 18:30:44','2026-09-09 18:30:44',NULL);
INSERT INTO `` (`content_id`,`menu_id`,`menu_name`,`menu_name_tamil`,`amount`,`image`,`content_text_english`,`content_text_tamil`,`ingredients_text_english`,`ingredients_text_tamil`,`net_weight`,`shelf_life`,`created_date`,`updated_date`,`created_by`) VALUES (14,14,'Ellu Satha Podi	','எள்ளு சாதப் பொடி',100.00,'1788958911513_Ellu-Satha-Podi.jpeg','Ellu Sadha Podi is a traditional South Indian spice powder made from sesame seeds, lentils, and aromatic spices. Sesame seeds are rich in calcium, iron, protein, healthy fats, and antioxidants that support overall health. Regular consumption may help strengthen bones and teeth, support heart health, and improve blood circulation. The dietary fiber in sesame seeds aids digestion and promotes a healthy digestive system. Ellu Sadha Podi also helps provide energy, supports healthy skin and hair, and contributes to overall well-being. When mixed with rice and consumed as part of a balanced diet, it serves as a nutritious and flavorful meal accompaniment.','எள்ளு சாதப் பொடி என்பது எள், பருப்புகள் மற்றும் நறுமண மசாலாப் பொருட்களைக் கொண்டு தயாரிக்கப்படும் பாரம்பரிய தென்னிந்திய உணவுப் பொடியாகும். எள்ளில் கால்சியம், இரும்புச்சத்து, புரதம், ஆரோக்கியமான கொழுப்புச் சத்துகள் மற்றும் ஆன்டி ஆக்சிடன்ட்கள் நிறைந்துள்ளன. இது எலும்புகள் மற்றும் பற்களை வலுப்படுத்தவும், இதய ஆரோக்கியத்தை மேம்படுத்தவும், ரத்த ஓட்டத்தை சீராக பராமரிக்கவும் உதவக்கூடும். இதில் உள்ள நார்ச்சத்து செரிமானத்தை மேம்படுத்தி குடல் ஆரோக்கியத்தை ஆதரிக்கிறது. மேலும், உடலுக்கு ஆற்றலை வழங்கி, தோல் மற்றும் தலைமுடி ஆரோக்கியத்தைப் பேணவும் உதவுகிறது. சாதத்துடன் கலந்து சமச்சீர் உணவின் ஒரு பகுதியாக உட்கொள்ளும்போது, எள்ளு சாதப் பொடி சுவையுடனும் சத்துடனும் உடலுக்கு பல ஆரோக்கிய நன்மைகளை வழங்குகிறது.','','','100 G','3 Month','2026-09-09 18:31:51','2026-09-09 18:31:51',NULL);
INSERT INTO `` (`content_id`,`menu_id`,`menu_name`,`menu_name_tamil`,`amount`,`image`,`content_text_english`,`content_text_tamil`,`ingredients_text_english`,`ingredients_text_tamil`,`net_weight`,`shelf_life`,`created_date`,`updated_date`,`created_by`) VALUES (15,15,'Ellu Thuvaiyal','எள்ளு துவையல்',150.00,'1788958995292_Ellu-Thuvaiyal.jpeg','Ellu Thuvaiyal (Sesame Chutney) is a traditional South Indian dish made primarily from sesame seeds, spices, and herbs. Sesame seeds are rich in calcium, iron, protein, healthy fats, and antioxidants, making them highly nutritious. Regular consumption may help strengthen bones and teeth, support heart health, and improve blood circulation. The fiber content aids digestion and promotes gut health. Sesame seeds also help provide sustained energy and support healthy skin and hair. When included as part of a balanced diet, Ellu Thuvaiyal can be a delicious and nutritious addition to everyday meals.','எள்ளுத் துவையல் என்பது எள், மசாலாப் பொருட்கள் மற்றும் மூலிகைப் பொருட்களைக் கொண்டு தயாரிக்கப்படும் பாரம்பரிய தென்னிந்திய உணவாகும். எள்ளில் கால்சியம், இரும்புச்சத்து, புரதம், ஆரோக்கியமான கொழுப்புச் சத்துகள் மற்றும் ஆன்டி ஆக்சிடன்ட்கள் அதிகளவில் உள்ளன. இது எலும்புகள் மற்றும் பற்களை வலுப்படுத்தவும், இதய ஆரோக்கியத்தை மேம்படுத்தவும், ரத்த ஓட்டத்தை சீராக பராமரிக்கவும் உதவக்கூடும். இதில் உள்ள நார்ச்சத்து செரிமானத்தை மேம்படுத்தி குடல் ஆரோக்கியத்தை ஆதரிக்கிறது. மேலும், உடலுக்கு நீடித்த ஆற்றலை வழங்குவதுடன், தோல் மற்றும் தலைமுடி ஆரோக்கியத்தையும் பேண உதவுகிறது. சமச்சீர் உணவுடன் சேர்த்து உட்கொள்ளும்போது, எள்ளுத் துவையல் சுவையுடனும் சத்துடனும் உடலுக்கு பல ஆரோக்கிய நன்மைகளை வழங்குகிறது.','','','100 G','1 Week','2026-09-09 18:33:15','2026-09-09 18:33:15',NULL);
INSERT INTO `` (`content_id`,`menu_id`,`menu_name`,`menu_name_tamil`,`amount`,`image`,`content_text_english`,`content_text_tamil`,`ingredients_text_english`,`ingredients_text_tamil`,`net_weight`,`shelf_life`,`created_date`,`updated_date`,`created_by`) VALUES (16,16,'Soththu Vadagam','சோற்று வடகம்',300.00,'1788960273468_Soththu-Vadagam.jpeg','Sothu Vadagam is a traditional South Indian condiment prepared using ingredients such as onions, garlic, cumin, mustard seeds, fenugreek, and other aromatic spices. It is commonly used to enhance the flavor of curries and gravies. The spices used in Sothu Vadagam help improve digestion, stimulate appetite, and reduce bloating and gas. Ingredients like garlic and cumin may support immunity and overall digestive health. Sothu Vadagam also adds aroma and taste to food, making meals more enjoyable. When consumed in moderation as part of a balanced diet, it can contribute to overall well-being.','சோத்து வடகம் என்பது வெங்காயம், பூண்டு, சீரகம், கடுகு, வெந்தயம் மற்றும் பல்வேறு நறுமண மசாலாப் பொருட்களைக் கொண்டு தயாரிக்கப்படும் பாரம்பரிய தென்னிந்திய உணவுப் பொருளாகும். இது பொதுவாக குழம்பு, சாம்பார் மற்றும் கறி வகைகளில் சுவை மற்றும் மணத்தை அதிகரிக்க பயன்படுத்தப்படுகிறது. இதில் உள்ள மசாலாப் பொருட்கள் செரிமானத்தை மேம்படுத்தவும், பசியைத் தூண்டவும், வயிற்று உப்புசம் மற்றும் வாயுத் தொல்லையைக் குறைக்கவும் உதவுகின்றன. பூண்டு மற்றும் சீரகம் போன்ற பொருட்கள் நோய் எதிர்ப்பு சக்தியை ஆதரிக்கவும், குடல் ஆரோக்கியத்தை மேம்படுத்தவும் உதவக்கூடும். சோத்து வடகம் உணவிற்கு தனித்துவமான மணத்தையும் சுவையையும் வழங்குவதுடன், அளவோடு பயன்படுத்தும்போது ஒட்டுமொத்த உடல் நலனுக்கும் பயனளிக்கிறது.','','','1 KG','3 Month','2026-09-09 18:54:33','2026-09-09 18:54:33',NULL);
INSERT INTO `` (`content_id`,`menu_id`,`menu_name`,`menu_name_tamil`,`amount`,`image`,`content_text_english`,`content_text_tamil`,`ingredients_text_english`,`ingredients_text_tamil`,`net_weight`,`shelf_life`,`created_date`,`updated_date`,`created_by`) VALUES (17,17,'Thalippu Vadagam','தாளிப்பு வடகம்',200.00,'1788960387410_Thalippu-Vadagam.jpeg','Thalippu Vadagam is a traditional South Indian seasoning made from ingredients such as onions, garlic, mustard seeds, cumin, fenugreek, and other aromatic spices. It is widely used for tempering curries, gravies, and traditional dishes. The spices present in Thalippu Vadagam help improve digestion, stimulate appetite, and reduce bloating and gas. Ingredients like garlic and fenugreek may support heart health and help strengthen the immune system. Its rich aroma and flavor enhance the taste of food while also contributing to overall digestive wellness. When consumed in moderation as part of a balanced diet, Thalippu Vadagam can be a flavorful and beneficial addition to daily meals.','தாளிப்பு வடகம் என்பது வெங்காயம், பூண்டு, கடுகு, சீரகம், வெந்தயம் மற்றும் பல்வேறு நறுமண மசாலாப் பொருட்களைக் கொண்டு தயாரிக்கப்படும் பாரம்பரிய தென்னிந்திய தாளிப்பு கலவையாகும். இது குழம்பு, சாம்பார் மற்றும் பல்வேறு உணவுகளில் தாளிப்பாக பயன்படுத்தப்படுகிறது. இதில் உள்ள மசாலாப் பொருட்கள் செரிமானத்தை மேம்படுத்தவும், பசியைத் தூண்டவும், வயிற்று உப்புசம் மற்றும் வாயுத் தொல்லையை குறைக்கவும் உதவுகின்றன. பூண்டு மற்றும் வெந்தயம் போன்ற பொருட்கள் இதய ஆரோக்கியத்தை ஆதரிக்கவும், நோய் எதிர்ப்பு சக்தியை மேம்படுத்தவும் உதவக்கூடும். தாளிப்பு வடகம் உணவிற்கு தனித்துவமான மணத்தையும் சுவையையும் வழங்குவதுடன், செரிமான ஆரோக்கியத்திற்கும் பயனளிக்கிறது. அளவோடு பயன்படுத்தும்போது, இது அன்றாட உணவில் சுவையுடனும் ஆரோக்கிய நன்மைகளுடனும் சிறந்த சேர்க்கையாக அமைகிறது.\n\nProvide your feedback on BizChat','','','100 G','3 Month','2026-09-09 18:56:27','2026-09-09 18:56:27',NULL);
INSERT INTO `` (`content_id`,`menu_id`,`menu_name`,`menu_name_tamil`,`amount`,`image`,`content_text_english`,`content_text_tamil`,`ingredients_text_english`,`ingredients_text_tamil`,`net_weight`,`shelf_life`,`created_date`,`updated_date`,`created_by`) VALUES (20,19,'Paruppu Satha Podi','பருப்பு சாத பொடி',100.00,'1789563321697_Paruppu-Satha-Podi.jpg','Paruppu Satha Podi is a nutritious traditional South Indian powder prepared from roasted lentils and aromatic spices. \nIt is rich in protein, fiber, vitamins, and minerals that help improve digestion, provide energy, and support overall health. \nWhen mixed with hot rice and ghee, it makes a healthy, tasty, and comforting meal that is easy to digest and suitable for people of all ages.','பருப்பு சாதப் பொடி என்பது வறுத்த பருப்புகள் மற்றும் நறுமணமிக்க மசாலாப்பொருட்களால் தயாரிக்கப்படும் சத்தான பாரம்பரிய உணவுப் பொடி ஆகும்.இதில் உள்ள புரதச்சத்து, நார்ச்சத்து, வைட்டமின்கள் மற்றும் தாதுக்கள் உடலுக்கு தேவையான சக்தியை வழங்கி, செரிமானத்தை மேம்படுத்தி, ஒட்டுமொத்த ஆரோக்கியத்தை ஆதரிக்கின்றன.சூடான சாதத்தில் நெய் சேர்த்து பருப்பு சாதப் பொடியை கலந்து சாப்பிடுவது சுவையுடன் கூடிய சத்தான உணவாகும்.','','','100 G','3 Month','2026-09-16 18:25:21','2026-09-16 18:25:21',NULL);
INSERT INTO `` (`content_id`,`menu_id`,`menu_name`,`menu_name_tamil`,`amount`,`image`,`content_text_english`,`content_text_tamil`,`ingredients_text_english`,`ingredients_text_tamil`,`net_weight`,`shelf_life`,`created_date`,`updated_date`,`created_by`) VALUES (21,20,'Aavaramboo Podi	','ஆவாரம்பூ பொடி',150.00,'1789563408461_Aavaramboo-Podi.jpeg','Aavaram Poo Podi is a traditional herbal powder prepared from dried Aavaram flowers. \nIt is valued for its cooling properties and is commonly used to support healthy blood sugar levels, \nimprove digestion, promote skin health, and enhance overall wellness. Rich in natural antioxidants, \nit helps protect the body from free radicals while providing a refreshing and nourishing addition to the diet.','ஆவாரம் பூ பொடி என்பது ஆவாரம் பூக்களை உலர்த்தி தயாரிக்கப்படும் பாரம்பரிய மூலிகைப் பொடி ஆகும். இது உடலுக்கு குளிர்ச்சி அளிப்பதுடன், இரத்த சர்க்கரை  அளவை சீராக வைத்திருக்க உதவுகிறது. மேலும் செரிமானத்தை மேம்படுத்தி, தோல் ஆரோக்கியத்தை பாதுகாத்து, உடலுக்கு தேவையான இயற்கை ஆன்டி-ஆக்ஸிடென்ட்களை வழங்குகிறது.  தினசரி உணவில் அளவோடு சேர்த்துக் கொண்டால் உடல் ஆரோக்கியத்திற்கும் புத்துணர்ச்சிக்கும் உதவியாக இருக்கும்.\n','','','100 G','3 Month','2026-09-16 18:26:48','2026-09-16 18:26:48',NULL);
INSERT INTO `` (`content_id`,`menu_id`,`menu_name`,`menu_name_tamil`,`amount`,`image`,`content_text_english`,`content_text_tamil`,`ingredients_text_english`,`ingredients_text_tamil`,`net_weight`,`shelf_life`,`created_date`,`updated_date`,`created_by`) VALUES (22,21,'Mudakathan Podi','முடக்கத்தான் பொடி',100.00,'1789563554951_Mudakathan-Podi.jpeg','Mudakathan Podi is a nutritious herbal powder prepared from Mudakathan leaves and aromatic spices. \nIt is traditionally valued for supporting joint and bone health, improving digestion, and enhancing overall wellness. \nRich in natural antioxidants and beneficial plant compounds, it helps maintain flexibility, supports immunity, \nand promotes a healthy lifestyle when included as part of a balanced diet.','முடக்கத்தான் பொடி என்பது முடக்கத்தான் கீரையிலிருந்து தயாரிக்கப்படும் பாரம்பரிய மூலிகை உணவுப் பொடி ஆகும். இது மூட்டு மற்றும் எலும்பு ஆரோக்கியத்தை \nஆதரிக்கவும், செரிமானத்தை மேம்படுத்தவும், உடல் நெகிழ்வுத்தன்மையை பராமரிக்கவும் உதவுகிறது. இதில் உள்ள இயற்கை சத்துக்கள் மற்றும் ஆன்டி-ஆக்ஸிடென்ட்கள் \nஉடலின் நோய் எதிர்ப்பு சக்தியை மேம்படுத்தி, ஒட்டுமொத்த ஆரோக்கியத்திற்கும் புத்துணர்ச்சிக்கும் துணைபுரிகின்றன.','','','100 G','3 Month','2026-09-16 18:29:14','2026-09-16 19:16:10',NULL);
INSERT INTO `` (`content_id`,`menu_id`,`menu_name`,`menu_name_tamil`,`amount`,`image`,`content_text_english`,`content_text_tamil`,`ingredients_text_english`,`ingredients_text_tamil`,`net_weight`,`shelf_life`,`created_date`,`updated_date`,`created_by`) VALUES (23,22,'Nalangu Maavu','நலங்கு மாவு',100.00,'1789563896484_Nalangu-Maavu.jpeg','Nalangu Maavu is a traditional herbal bathing powder prepared from a blend of natural ingredients and medicinal herbs. \nIt gently cleanses the skin, removes impurities, and helps maintain a healthy glow without the use of harsh chemicals. \nIts cooling and refreshing properties make it an excellent natural alternative to soap, helping to keep the skin soft, \nfresh, and well nourished.','நலங்கு மாவு என்பது பல இயற்கை மூலிகைகள் மற்றும் தானியங்களின் கலவையால் தயாரிக்கப்படும் பாரம்பரிய குளியல் பொடி ஆகும். இது சருமத்தில் உள்ள அழுக்குகள் மற்றும் \nஅதிகப்படியான எண்ணெயை மென்மையாக நீக்கி, சருமத்தை சுத்தமாகவும் ஆரோக்கியமாகவும் வைத்திருக்க உதவுகிறது. உடலுக்கு குளிர்ச்சியையும் புத்துணர்ச்சியையும் வழங்கும் \nநலங்கு மாவு, ரசாயன சோப்புகளுக்கு ஒரு சிறந்த இயற்கை மாற்றாக கருதப்படுகிறது.','','','100 G','3 Month','2026-09-16 18:34:56','2026-09-16 19:15:11',NULL);
INSERT INTO `` (`content_id`,`menu_id`,`menu_name`,`menu_name_tamil`,`amount`,`image`,`content_text_english`,`content_text_tamil`,`ingredients_text_english`,`ingredients_text_tamil`,`net_weight`,`shelf_life`,`created_date`,`updated_date`,`created_by`) VALUES (24,23,'Thoothuvalai Thuvaiyal','தூதுவளை துவையல்',150.00,'1789564022578_Thoothuvalai-Thuvaiyal.jpeg','Thoothuvalai Thuvaiyal is a nutritious herbal preparation made from fresh Thoothuvalai leaves and aromatic spices. \nIt is traditionally known for supporting respiratory health, soothing throat discomfort, and boosting immunity. \nRich in antioxidants and beneficial nutrients, this flavorful thuvaiyal can be enjoyed with rice or dosa as part \nof a balanced and healthy diet.','தூதுவளை துவையல் என்பது தூதுவளை இலைகள் மற்றும் நறுமண மசாலாப் பொருட்களால் தயாரிக்கப்படும் சத்தான பாரம்பரிய உணவாகும். \nஇது சுவாச மண்டல ஆரோக்கியத்தை ஆதரிப்பதோடு, இருமல் மற்றும் தொண்டை அசௌகரியத்தை குறைக்க உதவுகிறது. இதில் உள்ள இயற்கை சத்துக்கள் \nமற்றும் ஆன்டி-ஆக்ஸிடென்ட்கள் நோய் எதிர்ப்பு சக்தியை மேம்படுத்தி, உடலுக்கு புத்துணர்ச்சி அளித்து, ஒட்டுமொத்த ஆரோக்கியத்தையும் மேம்படுத்துகின்றன.','','','100 G','7 Days','2026-09-16 18:37:02','2026-09-16 19:16:43',NULL);
INSERT INTO `` (`content_id`,`menu_id`,`menu_name`,`menu_name_tamil`,`amount`,`image`,`content_text_english`,`content_text_tamil`,`ingredients_text_english`,`ingredients_text_tamil`,`net_weight`,`shelf_life`,`created_date`,`updated_date`,`created_by`) VALUES (25,24,'Thakkali Thuvaiyal','தக்காளி துவையல்',150.00,'1789564101003_Thakkali-Thuvaiyal.jpeg','Thakkali Thuvaiyal is a delicious and nutritious traditional South Indian chutney made from fresh \ntomatoes and aromatic spices. It is rich in antioxidants, vitamins, and minerals that help support \nheart health, immunity, digestion, and skin health. Its tangy taste and nutritional benefits make it \nan excellent accompaniment to rice, idli, dosa, and other traditional foods.','தக்காளி துவையல் என்பது தக்காளி மற்றும் நறுமண மசாலாப் பொருட்களால் தயாரிக்கப்படும் சத்தான பாரம்பரிய உணவாகும். இதில் உள்ள லைகோபீன், வைட்டமின்கள் மற்றும் தாதுக்கள் இதய ஆரோக்கியம், நோய் எதிர்ப்பு சக்தி, செரிமானம் மற்றும் சரும ஆரோக்கியத்தை ஆதரிக்க உதவுகின்றன. சாதம், இட்லி, தோசை போன்ற உணவுகளுடன் சேர்த்து சாப்பிடும்போது சுவையையும் சத்தையும் ஒருங்கே வழங்கும் சிறந்த உணவாகும்.','','','100 G','7 Days','2026-09-16 18:38:20','2026-09-16 18:38:20',NULL);
INSERT INTO `` (`content_id`,`menu_id`,`menu_name`,`menu_name_tamil`,`amount`,`image`,`content_text_english`,`content_text_tamil`,`ingredients_text_english`,`ingredients_text_tamil`,`net_weight`,`shelf_life`,`created_date`,`updated_date`,`created_by`) VALUES (26,25,'Marunthu Kulambu','மருந்து குழம்பு',150.00,'1789564164107_Marunthu-Kulambu.jpg','Marunthu Kulambu is a traditional medicinal gravy prepared using a blend of herbs and spices known for \ntheir health-promoting properties. It helps improve digestion, supports immunity, and provides relief from \ncommon seasonal ailments such as colds and coughs. Rich in antioxidants and natural nutrients, \nMarunthu Kulambu is a flavorful and nourishing addition to a balanced diet.','மருந்து குழம்பு என்பது பல்வேறு மூலிகைகள் மற்றும் மசாலாப் பொருட்களின் கலவையால் தயாரிக்கப்படும் பாரம்பரிய ஆரோக்கிய உணவாகும். இது செரிமானத்தை \nமேம்படுத்துவதோடு, நோய் எதிர்ப்பு சக்தியை அதிகரிக்கவும், சளி மற்றும் இருமல் போன்ற பருவகால உடல்நல பிரச்சனைகளில் நிவாரணம் அளிக்கவும் உதவுகிறது. \nஉடலுக்கு தேவையான இயற்கைச் சத்துக்களையும் ஆன்டி-ஆக்ஸிடென்ட்களையும் வழங்கி, ஒட்டுமொத்த ஆரோக்கியத்தையும் புத்துணர்ச்சியையும் மேம்படுத்துகிறது.','','','100 G','7 Days','2026-09-16 18:39:24','2026-09-16 18:39:24',NULL);
INSERT INTO `` (`content_id`,`menu_id`,`menu_name`,`menu_name_tamil`,`amount`,`image`,`content_text_english`,`content_text_tamil`,`ingredients_text_english`,`ingredients_text_tamil`,`net_weight`,`shelf_life`,`created_date`,`updated_date`,`created_by`) VALUES (27,26,'Hair Oil','தலைமுடி எண்ணெய்',200.00,'1789564962437_Hair-Oil.jpeg','Hair Oil is a traditional hair care product enriched with natural oils and herbs that nourish the scalp and strengthen the hair from the roots. Regular use helps moisturize the hair, reduce breakage, improve shine, and support healthy hair growth. It also helps maintain scalp health, leaving hair soft, manageable, and naturally beautiful.','முடி எண்ணெய் என்பது இயற்கை எண்ணெய்கள் மற்றும் மூலிகைகளின் கலவையால் தயாரிக்கப்படும் பாரம்பரிய தலைமுடி பராமரிப்பு தயாரிப்பாகும். இது தலையோட்டிக்கு ஊட்டச்சத்தை வழங்கி, முடி வேர்களை வலுப்படுத்தி, முடி உதிர்வை குறைக்க உதவுகிறது. தொடர்ந்து பயன்படுத்துவதன் மூலம் முடி மென்மையாகவும், பளபளப்பாகவும், ஆரோக்கியமாகவும் காணப்படுவதுடன், தலையோட்டியின் ஆரோக்கியத்தையும் பராமரிக்க உதவுகிறது.','','','100 M','3 Month','2026-09-16 18:52:42','2026-09-16 18:52:42',NULL);
INSERT INTO `` (`content_id`,`menu_id`,`menu_name`,`menu_name_tamil`,`amount`,`image`,`content_text_english`,`content_text_tamil`,`ingredients_text_english`,`ingredients_text_tamil`,`net_weight`,`shelf_life`,`created_date`,`updated_date`,`created_by`) VALUES (28,27,'Hair Pack','ஹேர் பேக்',200.00,'1789565006717_Hair-Pack.jpeg','Hair Pack is a nourishing hair care treatment prepared from natural and herbal ingredients that help strengthen and revitalize the hair. It deeply conditions the scalp, reduces dryness, promotes healthy hair growth, and improves hair texture. Regular use of a hair pack can make hair softer, shinier, and healthier while supporting overall scalp health.','முடி பேக் என்பது இயற்கை மற்றும் மூலிகைப் பொருட்களால் தயாரிக்கப்படும் ஒரு சிறந்த தலைமுடி பராமரிப்பு முறையாகும். இது தலையோட்டிக்கு ஆழமான ஊட்டச்சத்தை வழங்கி, முடி வேர்களை வலுப்படுத்தி, முடி உதிர்வைக் குறைக்க உதவுகிறது. தொடர்ந்து பயன்படுத்துவதன் மூலம் முடி மென்மையாகவும், பளபளப்பாகவும், ஆரோக்கியமாகவும் மாறுவதுடன், தலையோட்டியின் ஆரோக்கியத்தையும் பாதுகாக்க உதவுகிறது.','','','100 G','3 Month','2026-09-16 18:53:26','2026-09-16 18:53:26',NULL);
INSERT INTO `` (`content_id`,`menu_id`,`menu_name`,`menu_name_tamil`,`amount`,`image`,`content_text_english`,`content_text_tamil`,`ingredients_text_english`,`ingredients_text_tamil`,`net_weight`,`shelf_life`,`created_date`,`updated_date`,`created_by`) VALUES (29,28,'Nallennai','நல்லெண்ணெய்',600.00,'1789565050147_Nallennai.jpeg','Nallennai, also known as sesame oil or gingelly oil, is a nutritious traditional cooking oil valued for its rich content of healthy fats, antioxidants, vitamins, and minerals. It supports heart health, promotes healthy skin and hair, aids digestion, and contributes to overall well-being. Its distinctive flavor and nutritional benefits make it an important part of a healthy diet.','நல்லெண்ணெய் அல்லது எள் எண்ணெய் என்பது பல தலைமுறைகளாக பயன்படுத்தப்பட்டு வரும் சத்தான பாரம்பரிய எண்ணெய் ஆகும். இதில் உள்ள நல்ல கொழுப்புச் சத்துக்கள், ஆன்டி-ஆக்ஸிடென்ட்கள், வைட்டமின்கள் மற்றும் தாதுக்கள் இதய ஆரோக்கியம், எலும்பு ஆரோக்கியம், செரிமானம், சருமம் மற்றும் முடி ஆரோக்கியத்தை மேம்படுத்த உதவுகின்றன. தினசரி உணவில் அளவோடு பயன்படுத்தினால் ஒட்டுமொத்த உடல் நலனையும் ஆதரிக்கக்கூடிய சிறந்த இயற்கை உணவுப் பொருளாகும்.','','','1 Liter','6 Month','2026-09-16 18:54:10','2026-09-16 19:00:33',NULL);
